<script setup lang="ts">
import { onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { qualityApi, issues, statuses, type QualitySummary, type QualityRecord } from '../quality/api'
import QualityCharts from '../quality/QualityCharts.vue'
import { dateText, errorText } from '../api'
const filter = reactive({ rating: '', startDate: '', endDate: '' }), page = ref(1), pageSize = 20
const summary = ref<QualitySummary | null>(null), items = ref<QualityRecord[]>([]), total = ref(0), loading = ref(false), error = ref('')
const editing = ref<QualityRecord | null>(null), dialog = ref(false), saving = ref(false), reviewError = ref('')
const form = reactive({ issueType: 'UNCLASSIFIED', handlingStatus: 'OPEN', adminNote: '', version: 0 })
let generation = 0, alive = true
onBeforeUnmount(() => { alive = false; generation++ })
async function load() {
  const version = ++generation; loading.value = true; error.value = ''; summary.value = null; items.value = []
  const params = { rating: filter.rating || undefined, startDate: filter.startDate || undefined, endDate: filter.endDate || undefined }
  try {
    const [stats, records] = await Promise.all([qualityApi.summary(params), qualityApi.list({ ...params, page: page.value, pageSize })])
    if (!alive || version !== generation) return
    summary.value = stats; items.value = records.items; total.value = records.total
  } catch(e) { if (alive && version === generation) { error.value = errorText(e); total.value = 0 } }
  finally { if (alive && version === generation) loading.value = false }
}
function search() { page.value = 1; void load() }
function reset() { Object.assign(filter,{rating:'',startDate:'',endDate:''}); search() }
function review(item: QualityRecord) { editing.value = item; Object.assign(form, { issueType:item.issueType,handlingStatus:item.handlingStatus,adminNote:item.adminNote,version:item.version }); reviewError.value='';dialog.value=true }
async function save() {
  if (!editing.value || saving.value) return
  saving.value=true;reviewError.value=''
  try { await qualityApi.review(editing.value.id,{...form});if(alive){dialog.value=false;ElMessage.success('处理结果已保存');await load()} }
  catch(e) { if(alive)reviewError.value=errorText(e) }
  finally {saving.value=false}
}
onMounted(load)
</script>
<template><div class="admin-page quality-page"><div class="page-intro"><div><div class="eyebrow">管理与治理 / 用户反馈</div><h1>AI 问答质量分析</h1><p>从用户反馈发现问题，让校园问答持续变好。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-form class="quality-filters" inline @submit.prevent="search"><el-form-item label="评价类型"><el-select v-model="filter.rating" aria-label="评价类型" style="width:150px"><el-option label="全部评价" value="" /><el-option label="回复优秀" value="POSITIVE" /><el-option label="回复不佳" value="NEGATIVE" /></el-select></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="filter.startDate" type="date" value-format="YYYY-MM-DD" style="width:160px" aria-label="开始日期" /></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="filter.endDate" type="date" value-format="YYYY-MM-DD" style="width:160px" aria-label="结束日期" /></el-form-item><el-form-item><el-button type="primary" native-type="submit">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon /><div v-loading="loading"><p class="quality-hint">数据范围：{{ summary?.accessScope === 'ALL' ? '全校问答反馈' : summary?.accessScope === 'ASSIGNED' ? '已授权用户的问答反馈' : '等待加载' }}。统计当前有效评价，日期按最近一次评价或修改时间筛选；未指定日期时趋势展示最近30天。</p><div class="quality-stats"><div v-for="(card,i) in ['累计评价','回复优秀','回复不佳','好评率']" :key="card" class="stat-card"><span>{{ card }}</span><strong>{{ summary ? [summary.total,summary.positive,summary.negative,summary.total ? summary.positiveRate+'%' : '—'][i] : '—' }}</strong></div></div><QualityCharts v-if="summary" :data="summary" /><section class="panel-card"><div class="panel-head"><div><h2>评价记录与差评处理</h2><p>结合用户问题、回答和知识引用进行人工分析</p></div><el-button @click="filter.rating='NEGATIVE';search()">只看差评</el-button></div><el-empty v-if="!loading && !items.length && !error" description="当前筛选条件下暂无评价" /><article v-for="item in items" :key="item.id" class="quality-record"><div class="quality-record-head"><el-tag :type="item.rating === 'NEGATIVE' ? 'danger' : 'success'" effect="plain">{{ item.rating === 'NEGATIVE' ? '回复不佳' : '回复优秀' }}</el-tag><time>评价时间：{{ dateText(item.updatedAt) }}</time></div><h3>{{ item.question }}</h3><details><summary>查看 AI 回答与知识引用</summary><p>{{ item.answer }}</p><div v-for="s in item.response?.sources" :key="`${s.documentId}:${s.chunkIndex}`" class="quality-source"><strong>{{ s.fileName }} · {{ s.pageNumber == null ? '无页码' : `第 ${s.pageNumber} 页` }} · Chunk {{ s.documentId }}:{{ s.chunkIndex }}</strong><p>{{ s.content }}</p></div><p v-if="!item.response?.sources?.length">没有知识库引用。可检查知识库覆盖范围与检索结果。</p><div v-if="item.response?.service" class="quality-source">办事引导：{{ item.response.service.name }}<br>来源：{{ item.response.source?.title || item.response.service.sourceTitle || '未提供' }}<br>文档：{{ item.response.source?.documentId || item.response.service.sourceDocumentId || '未提供' }}</div></details><div v-if="item.rating === 'NEGATIVE'" class="quality-record-head"><span class="quality-hint">{{ issues[item.issueType] }} · {{ statuses[item.handlingStatus] }}</span><el-button size="small" @click="review(item)">标记与处理</el-button></div><p v-if="item.adminNote">处理备注：{{ item.adminNote }}</p></article><div class="table-footer"><span>共 {{ total }} 条评价</span><el-pagination v-model:current-page="page" :total="total" :page-size="pageSize" layout="prev, pager, next" @current-change="load" /></div></section></div><el-dialog v-model="dialog" title="差评标记与处理" width="min(520px,92vw)"><p class="quality-hint">原因由管理员人工判断，请结合原问题、回答及引用核查。</p><el-form label-position="top" @submit.prevent="save"><el-form-item label="问题原因"><el-select v-model="form.issueType" aria-label="问题原因"><el-option v-for="(label,value) in issues" :key="value" :value="value" :label="label" /></el-select></el-form-item><el-form-item label="处理状态"><el-select v-model="form.handlingStatus" aria-label="处理状态"><el-option v-for="(label,value) in statuses" :key="value" :value="value" :label="label" /></el-select></el-form-item><el-form-item label="处理备注"><el-input v-model="form.adminNote" aria-label="处理备注" type="textarea" :rows="4" maxlength="2000" show-word-limit /></el-form-item><el-alert v-if="reviewError" :title="reviewError" type="error" :closable="false" /><el-button type="primary" native-type="submit" :loading="saving">保存处理结果</el-button></el-form></el-dialog></div></template>
<style scoped>.quality-filters{display:flex;flex-wrap:wrap}.quality-hint{font-size:12px;line-height:1.8;color:var(--el-text-color-secondary)}.quality-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.quality-stats strong{font-size:32px}.quality-record{padding:20px 26px;border-top:1px solid var(--el-border-color-light)}.quality-record-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.quality-record time{font-size:12px;color:var(--el-text-color-secondary)}.quality-record h3{font-size:15px;line-height:1.7;overflow-wrap:anywhere}.quality-record p{font-size:13px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}.quality-record summary{font-size:12px;color:var(--el-color-primary);cursor:pointer;margin-bottom:12px}.quality-source{padding:12px;background:var(--el-fill-color-light);border-radius:8px;margin:8px 0;font-size:12px;overflow-wrap:anywhere}@media(max-width:760px){.quality-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.quality-record{padding:16px}.quality-page{min-width:0}.quality-filters .el-form-item{margin-right:8px}}</style>
